/**
 * Parse a positive integer from an environment variable value.
 * Returns `fallback` if the value is not a finite positive integer.
 *
 * @param {string|undefined} value - Raw env var value
 * @param {number} fallback - Default to use when value is invalid
 * @returns {number}
 */
const parsePositiveInt = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

/**
 * Parse a boolean from an environment variable value.
 * Accepts "true", "1", "yes", "y", "on" as truthy and
 * "false", "0", "no", "n", "off" as falsy (case-insensitive).
 * Returns `defaultValue` for unset or unrecognised values.
 *
 * @param {string|undefined|null} value - Raw env var value
 * @param {boolean} [defaultValue=false]
 * @returns {boolean}
 */
const boolEnv = (value, defaultValue = false) => {
  if (value === undefined || value === null) return defaultValue;
  const normalized = value.toString().trim().toLowerCase();
  if (['true', '1', 'yes', 'y', 'on'].includes(normalized)) return true;
  if (['false', '0', 'no', 'n', 'off'].includes(normalized)) return false;
  return defaultValue;
};

module.exports = { parsePositiveInt, boolEnv };
